package ai.decisionos.aside;
import android.content.*;import android.widget.*;import android.view.*;import org.json.*;import java.util.*;
/** Durable school requests and observed events, displayed inside the owning chat. */
final class SchoolChatWork {
 static final String[][] ROUTES={
 {"pdf","PDF|pdf|강의자료.*번역|번역.*강의자료"},{"team","팀플|팀 프로젝트|팀플레이|발표자료|발표 자료"},{"flirt","플러팅|썸|답장.*비교|회신.*비교"},{"lecture","동시.*통역|실시간.*통역|강의.*통역"},
 {"books","교재|책방|중고.*책"},{"review","강의평.*(등록|작성|남겨|써)|수강평|티켓.*10"},{"course","수강.*우선|강의평.*읽|시간표|수강신청"},{"professor","교수.*메일|병결|점수.*정정|전공.*상담|시험.*문의"},
 {"assignment","과제.*(해줘|작성|완수|제출|다운|만들|대신)|과제$"},{"ktx","KTX|ktx|코레일|본가|기차"},{"concert","콘서트|공연.*티켓"},{"outfit","무신사|4910|축제.*옷|옷.*주문"},
 {"bb_alerts","과제|시험|오픈북|announcements|messages|블랙보드.*공지"},
 {"application","공모전|신청서|장학.*신청|지원사업|인턴십.*초안"},{"community","동아리|캠퍼스픽|랩실|취업|자격증|축제"},{"notices","포털|포탈|장학|학점교류|복학|기말|계절학기|박사|졸업|몰입캠프|정원|공지"}};
 static CampusWorkflows.Flow match(String text){for(String[] r:ROUTES)if(java.util.regex.Pattern.compile(r[1],java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text).find())return CampusWorkflows.get(r[0]);return null;}
 static boolean campusExecutor(String flow){return Arrays.asList("notices","application","professor","course","bb_alerts","assignment","pdf","team").contains(flow);}
 static boolean handle(GoalChatUi c,String text){if(!"grades".equals(c.character))return false;
  if(text.matches(".*(알림|감시|주기|공지).*(꺼|끄|중지|그만).*")){CampusNoticeMonitor.stop(c.a);BlackboardNoticeMonitor.stop(c.a);c.a.getSharedPreferences("nubi_campus_ui",0).edit().putBoolean("chat_watch",false).apply();reply(c,text,"학교 소식 주기 확인을 껐어. 기존 대화와 기록은 그대로 남겨 둘게.","");return true;}
  if(text.matches(".*(자동|주기|계속).*(알려|감시|확인).*")){watch(c);reply(c,text,"포털·Blackboard 주기 확인을 요청했어. 새로 확인한 소식은 이 채팅에 남길게. 학교 로그인과 Android 실행 상태에 따라 확인이 늦어질 수 있어.","");return true;}
  if(text.matches(".*(진행|내 작업|작업 상태).*")){SchoolChatUi.tools(c,"jobs");return true;}
  CampusWorkflows.Flow f=match(text);if(f==null)return false;if(f.id.equals("lecture")){reply(c,text,"강의 구간별 통역을 열게. 시작을 누르면 Android 음성 인식 결과를 Qwen으로 번역해. 끝난 구간은 검토해서 이 대화에 보관할 수 있어.","");new LectureInterpretation(c).show();return true;}
  JSONObject job=new JSONObject();GoalStore.put(job,"flow",f.id);GoalStore.put(job,"title",f.title);GoalStore.put(job,"context",text);GoalStore.put(job,"state","draft");GoalStore.put(job,"goal",c.goalId);GoalStore.put(job,"conversation",c.conversationId);String id;try(CampusFlowStore store=new CampusFlowStore(c.a)){id=store.save("jobs",job);}
  reply(c,text,"좋아, "+f.title+"부터 준비할게. 요청과 진행 기록은 아래에 남겨 둘게.",id);
  // Execute supported public exploration automatically. Other tasks stay visibly pending until their adapter is available.
  if((campusExecutor(f.id)||Arrays.asList("community","ktx","concert","outfit","books","team").contains(f.id))&&c.a.relay.connected())new CampusHubUi(c.companion).send(job);
  return true;
 }
 static void reply(GoalChatUi c,String user,String answer,String id){c.history.put(c.message("user",user));JSONObject m=c.message("assistant",answer);if(!id.isEmpty())GoalStore.put(m,"campusJobId",id);c.history.put(m);c.input.setText("");c.save();c.render();}
 static void watch(GoalChatUi c){boolean portal=CampusNoticeMonitor.schedule(c.a),bb=BlackboardNoticeMonitor.schedule(c.a,false);CampusNoticeMonitor.scheduleNow(c.a);BlackboardNoticeMonitor.schedule(c.a,true);c.a.getSharedPreferences("nubi_campus_ui",0).edit().putBoolean("chat_watch",portal&&bb).apply();if(android.os.Build.VERSION.SDK_INT>=33&&c.a.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)c.a.requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},901);}
 static String status(JSONObject job){String state=job.optString("state");if(state.equals("requested"))return "실행 요청됨 · 결과 대기";if(state.equals("review"))return "결과 도착 · 검토 필요";if(state.equals("approved"))return "초안 검토 완료 · 외부 실행은 미확인";return "요청 저장됨 · 원문·실행 연결 확인 필요";}
 static void jobCard(GoalChatUi c,LinearLayout box,String id){try(CampusFlowStore store=new CampusFlowStore(c.a)){JSONObject job=store.get(id);if(!job.has("id"))return;if(!job.optString("goal").equals(c.goalId)||!job.optString("conversation").equals(c.conversationId))return;new CampusHubUi(c.companion).sync(job,store);CampusWorkflows.Flow f=CampusWorkflows.get(job.optString("flow"));box.addView(c.a.txt(f.title+"\n"+status(job),14,NubiCompanionUi.INK,true),Ui.match(c.a,-2,12));box.addView(c.a.txt(f.detail,13,NubiCompanionUi.MUTED,false),Ui.match(c.a,-2,6));if(job.optString("state").equals("draft"))box.addView(c.a.txt("현재 조회·초안 준비 단계야. 외부 AI 동시 실행, 파일 업로드, 발송·제출·결제는 전용 연결이 필요해.",12,NubiCompanionUi.MUTED,false),Ui.match(c.a,-2,6));Button review=SchoolChatUi.secondary(c,"요청·초안 확인");review.setOnClickListener(v->new CampusHubUi(c.companion).job(job));box.addView(review,Ui.match(c.a,-2,8));Button source=SchoolChatUi.secondary(c,CampusWorkflows.service(f.source)[1]+" 원문 열기");source.setOnClickListener(v->new CampusHubUi(c.companion).openService(f.source));box.addView(source,Ui.match(c.a,-2,4));}}
 static String eventId(String service,String key,String title){return "school-event-"+CampusNoticeMonitor.hash(service+"\n"+key+"\n"+title);}
 static synchronized void publish(Context c,String service,String key,String title,String text,String url,String date){if(title.trim().isEmpty())return;String id=eventId(service,key,title);try(CampusFlowStore store=new CampusFlowStore(c)){JSONObject prior=store.get(id);String fingerprint=CampusNoticeMonitor.hash(title+"\n"+text+"\n"+date);if(fingerprint.equals(prior.optString("fingerprint")))return;JSONObject e=new JSONObject();GoalStore.put(e,"id",id);GoalStore.put(e,"service",service);GoalStore.put(e,"title",title);GoalStore.put(e,"text",text);GoalStore.put(e,"url",url);GoalStore.put(e,"date",date);GoalStore.put(e,"origin","observed");GoalStore.put(e,"fingerprint",fingerprint);GoalStore.put(e,"signal",CampusSignal.extract(title,text,url,date,System.currentTimeMillis()));store.save("chat_events",e);}c.getSharedPreferences("nubi_campus_ui",0).edit().putLong("events_revision",System.nanoTime()).apply();}
 static void events(GoalChatUi c){if(!"grades".equals(c.character))return;try(CampusFlowStore store=new CampusFlowStore(c.a)){List<JSONObject> rows=store.list("chat_events");if(rows.isEmpty())return;rows=new ArrayList<>(rows.subList(0,Math.min(12,rows.size())));Collections.reverse(rows);for(JSONObject e:rows){LinearLayout box=c.box(NubiCompanionUi.PANEL,14);box.setBackground(Ui.bg(NubiCompanionUi.PANEL,18,c.a));box.addView(c.a.txt("학교 소식 · "+e.optString("title"),16,NubiCompanionUi.INK,true));box.addView(c.a.txt(e.optString("date")+" · 원문 확인 시각 "+new java.util.Date(e.optLong("updated"))+"\n"+e.optString("text"),13,NubiCompanionUi.MUTED,false),Ui.match(c.a,-2,8));Button read=SchoolChatUi.secondary(c,"원문 확인");read.setOnClickListener(v->c.showSource(e.optString("url")));box.addView(read);Button prepare=SchoolChatUi.secondary(c,"이 소식으로 준비해 줘");prepare.setOnClickListener(v->c.draft("이 공지의 대상·기한을 확인하고 필요한 신청서 초안을 준비해줘.\n출처: "+e.optString("url")+"\n"+e.optString("title")+"\n"+e.optString("text")));box.addView(prepare);c.messages.addView(box,Ui.match(c.a,-2,8));}}}
}
